// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// 本域进程存活
	// (GET /healthz)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)
	// 本域启动/恢复就绪
	// (GET /readyz)
	Ready(ctx context.Context, request ReadyRequestObject) (ReadyResponseObject, error)
	// 保存单条可关闭公告横幅
	// (PUT /v1/banner)
	UpdateBanner(ctx context.Context, request UpdateBannerRequestObject) (UpdateBannerResponseObject, error)
	// 取得可恢复的数据屏障
	// (POST /v1/barriers)
	AcquireBarrier(ctx context.Context, request AcquireBarrierRequestObject) (AcquireBarrierResponseObject, error)
	// 释放屏障
	// (DELETE /v1/barriers/{barrierId})
	ReleaseBarrier(ctx context.Context, request ReleaseBarrierRequestObject) (ReleaseBarrierResponseObject, error)
	// 更新站名/logo/图标/主题色/默认分享图
	// (PUT /v1/branding)
	UpdateBranding(ctx context.Context, request UpdateBrandingRequestObject) (UpdateBrandingResponseObject, error)
	// 读取后台站点配置
	// (GET /v1/config)
	ReadSiteConfig(ctx context.Context, request ReadSiteConfigRequestObject) (ReadSiteConfigResponseObject, error)
	// 更新站点常规配置
	// (PUT /v1/config)
	UpdateSiteConfig(ctx context.Context, request UpdateSiteConfigRequestObject) (UpdateSiteConfigResponseObject, error)
	// 站点设置历史
	// (GET /v1/config/history)
	ReadConfigHistory(ctx context.Context, request ReadConfigHistoryRequestObject) (ReadConfigHistoryResponseObject, error)
	// 回滚站点设置
	// (POST /v1/config/history/{revisionId}:restore)
	RestoreConfigRevision(ctx context.Context, request RestoreConfigRevisionRequestObject) (RestoreConfigRevisionResponseObject, error)
	// 更新页脚版权/自定义链接/ICP备案/源码链接
	// (PUT /v1/footer)
	UpdateFooter(ctx context.Context, request UpdateFooterRequestObject) (UpdateFooterResponseObject, error)
	// 配置首页介绍、卡片和精选文档
	// (PUT /v1/home)
	UpdateHome(ctx context.Context, request UpdateHomeRequestObject) (UpdateHomeResponseObject, error)
	// 读取可公开的首页配置
	// (GET /v1/home/public)
	ReadPublicHome(ctx context.Context, request ReadPublicHomeRequestObject) (ReadPublicHomeResponseObject, error)
	// 读取安全初始化阶段
	// (GET /v1/initialization)
	ReadInitializationStatus(ctx context.Context, request ReadInitializationStatusRequestObject) (ReadInitializationStatusResponseObject, error)
	// 无需AI完成首站点初始化
	// (POST /v1/initialization)
	InitializeSite(ctx context.Context, request InitializeSiteRequestObject) (InitializeSiteResponseObject, error)
	// 取消尚未持久commit的初始化
	// (POST /v1/initialization:abort)
	AbortInitialization(ctx context.Context, request AbortInitializationRequestObject) (AbortInitializationResponseObject, error)
	// 恢复崩溃或依赖断开的初始化阶段
	// (POST /v1/initialization:resume)
	ResumeInitialization(ctx context.Context, request ResumeInitializationRequestObject) (ResumeInitializationResponseObject, error)
	// 读取已提交的本域不可变对象原始字节
	// (GET /v1/objects/{objectId})
	ReadConfigObject(ctx context.Context, request ReadConfigObjectRequestObject) (ReadConfigObjectResponseObject, error)
	// 媒体核对首页资源来源持久决定
	// (GET /v1/reference-decisions/{sourceOperationId})
	ReadHomeReferenceDecision(ctx context.Context, request ReadHomeReferenceDecisionRequestObject) (ReadHomeReferenceDecisionResponseObject, error)
	// 站点设置完整资源引用
	// (GET /v1/resource-references)
	ListResourceReferences(ctx context.Context, request ListResourceReferencesRequestObject) (ListResourceReferencesResponseObject, error)
	// 读取独立控制库权威运行状态
	// (GET /v1/runtime-state)
	ReadRuntimeState(ctx context.Context, request ReadRuntimeStateRequestObject) (ReadRuntimeStateResponseObject, error)
	// 登记域恢复切换/换回回执
	// (POST /v1/runtime-state/activations)
	RegisterActivation(ctx context.Context, request RegisterActivationRequestObject) (RegisterActivationResponseObject, error)
	// 按CAS切换epoch与维护阶段
	// (POST /v1/runtime-state:transition)
	TransitionRuntimeState(ctx context.Context, request TransitionRuntimeStateRequestObject) (TransitionRuntimeStateResponseObject, error)
	// 删除恢复暂存或换出的旧数据目录
	// (POST /v1/snapshots:discard)
	DiscardSnapshot(ctx context.Context, request DiscardSnapshotRequestObject) (DiscardSnapshotResponseObject, error)
	// 导出屏障水位的一致快照
	// (POST /v1/snapshots:export)
	ExportSnapshot(ctx context.Context, request ExportSnapshotRequestObject) (ExportSnapshotResponseObject, error)
	// 暂存本域恢复归档，不改active目录
	// (POST /v1/snapshots:stage)
	StageSnapshot(ctx context.Context, request StageSnapshotRequestObject) (StageSnapshotResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// Health operation middleware
func (sh *strictHandler) Health(w http.ResponseWriter, r *http.Request) {
	var request HealthRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.Health(ctx, request.(HealthRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Health")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(HealthResponseObject); ok {
		if err := validResponse.VisitHealthResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

